{"command":"npm test && node -e "
import assert from 'node:assert/strict';
import { lowerBlockScope } from './src/compiler/ir_lowering.mjs';
import { SymbolTable } from './src/compiler/symbol_table.mjs';
import { DiagnosticBag } from './src/compiler/diagnostic_bag.mjs';
import { ByteWriter } from './src/lib/byte_writer.mjs';

const symTab = new SymbolTable();
const diag = new DiagnosticBag();
const buf = new ByteWriter();

const resOk = lowerBlockScope({
  declarations: [
    { name: 'a', kind: 'let', initOffset: 16 },
    { name: 'b', kind: 'const', initOffset: 32 },
  ],
}, symTab, diag, buf);

assert.equal(resOk.isOk, true);
assert.deepEqual(resOk.value, { count: 2, bytesHex: '0000001000000020' });
assert.equal(symTab.frames.length, 1);
assert.equal(diag.items.length, 0);

const buf2 = new ByteWriter();
const resDup = lowerBlockScope({
  declarations: [
    { name: 'x', kind: 'let', initOffset: 4 },
    { name: 'x', kind: 'const', initOffset: 8 },
  ],
}, symTab, diag, buf2);

assert.equal(resDup.isOk, false);
assert.equal(resDup.errorCode, 'E_DUPLICATE_BINDING');
assert.equal(resDup.value, 'x');
assert.equal(symTab.frames.length, 1);
assert.deepEqual(diag.items, [{ code: 'E_DUPLICATE_BINDING', message: 'Duplicate: x', offset: 8 }]);
assert.equal(buf2.toHex(), '00000004');
console.log('Integration check passed');
""}

